import java.sql.Connection;
import java.sql.PreparedStatement; // Proper API use to prevent injection
import java.sql.ResultSet;
import javax.naming.InitialContext;
import javax.naming.NamingException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.sql.DataSource;

public class LoginServletGood extends HttpServlet {
    private DataSource dataSource;

    @Override
    public void init() {
        try {
            // Prefer a pooled DataSource (e.g., via JNDI) over DriverManager
            InitialContext ctx = new InitialContext();
            dataSource = (DataSource) ctx.lookup("java:comp/env/jdbc/AppDS");
        } catch (NamingException e) {
            // Log internally; avoid exposing details to users
            getServletContext().log("DataSource init failed", e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String user = req.getParameter("user");
        String password = req.getParameter("password");

        // Defensive coding: null-check and basic length constraints to reduce abuse
        if (user == null || password == null || user.length() > 100 || password.length() > 100) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }

        // Use a parameterized PreparedStatement to prevent SQL injection (fixes the vulnerable pattern)
        String sql = "SELECT id FROM users WHERE username = ? AND password = ?";

        try (Connection conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, user);
            ps.setString(2, password); // In production, store and compare hashed passwords (e.g., BCrypt)

            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    // Escape output to reduce XSS risk when echoing user-controlled data
                    resp.getWriter().write("Welcome " + escapeHtml(user));
                } else {
                    resp.getWriter().write("Invalid credentials");
                }
            }
        } catch (Exception e) {
            // Log server-side, return a generic error to the client
            getServletContext().log("Login error", e);
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
        }
    }

    private String escapeHtml(String s) {
