      "type": "string",
      "description": "unique identifier for this beta cruiser",
      "examples": ["[beta-cruiser-id]"]
    },
    "name": {
      "type": "string",
      "minLength": 1
    },
    "class": {
      "const": "beta cruiser",
      "description": "fixed class name"
    },
