      "type": "string",
      "description": "fleet registry identifier",
      "pattern": "^bc-[0-9]{5}$",
      "examples": ["bc-12345", "[registry-id]"]
    },
    "manufacturer": {
      "type": "string"
    },
    "status": {
      "type": "string",
      "enum": ["active", "maintenance", "decommissioned"]
    },
    "dimensions": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "length_m": { "type": "number", "minimum": 0 },
        "beam_m": { "type": "number", "minimum": 0 },
        "height_m": { "type": "number", "minimum": 0 },
        "mass_t": { "type": "number", "minimum": 0 }
      },
      "required": ["length_m", "beam_m", "height_m", "mass_t"]
    },
    "propulsion": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "sublight": {
          "type": "string",
          "enum": ["ion", "plasma", "fusion"],
          "examples": ["[sublight-drive-type]"]
        },
        "ftl": {
          "type": "string",
          "enum": ["warp", "jump", "fold"],
          "examples": ["[ftl-drive-type]"]
        },
        "max_delta_v_ms": {
          "type": "number",
          "minimum": 0
        }
      },
      "required": ["sublight", "ftl"]
    },
    "power": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "reactor_type": {
          "type": "string",
          "enum": ["fusion", "antimatter", "fission"],
          "examples": ["[reactor-type]"]
        },
        "output_mw": {
          "type": "number",
          "minimum": 0
        }
      },
      "required": ["reactor_type", "output_mw"]
    },
    "crew": {
      "type": "object",
      "properties": {
        "complement": { "type": "integer", "minimum": 0 },
        "roles": {
          "type": "array",
          "items": { "type": "string" },
          "examples": [["captain", "pilot", "[add-role]"]]
        },
        "manifest": {
          "type": "array",
          "minItems": 0,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "crew_id": { "type": "string", "examples": ["[crew-id]"] },
              "name": { "type": "string", "examples": ["[crew-member-name]"] },
              "role": { "type": "string" },
              "rank": { "type": "string" }
            },
            "required": ["crew_id", "name", "role"]
          }
        }
      },
      "required": ["complement"]
    },
    "armament": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "type": {
            "type": "string",
            "enum": ["laser", "railgun", "missile", "point-defense"],
            "examples": ["[weapon-type]"]
          },
          "count": { "type": "integer", "minimum": 0 },
          "mount": { "type": "string", "enum": ["fixed", "turret", "internal"] },
          "notes": { "type": "string", "maxLength": 200, "examples": ["[armament-notes]"] }
        },
        "required": ["type", "count"]
      }
    },
    "defense": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "shields": { "type": "boolean" },
        "hull_rating": { "type": "integer", "minimum": 0 },
        "countermeasures": {
          "type": "array",
          "items": { "type": "string" },
          "examples": [["chaff", "flares", "[countermeasure]"]]
        }
      }
    },
    "sensors": {
      "type": "array",
      "items": { "type": "string" },
      "examples": [["radar", "lidar", "gravimetric", "[sensor]"]]
    },
    "hangar": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "capacity": { "type": "integer", "minimum": 0 },
        "craft": {
          "type": "array",
          "items": { "type": "string" },
          "examples": [["interceptor", "[aux-craft]"]]
        }
      }
    },
    "callsign": { "type": "string", "examples": ["[call-sign]"] },
    "commissioned_date": { "type": "string", "format": "date" },
    "notes": { "type": "string", "examples": ["[free-text-notes]"] }
  },
  "required": ["id", "name", "class", "registry_id", "status", "dimensions", "propulsion", "power", "crew"]
}

