{
  "title": "Assessing the relationship between fast-paced environment exposure and ADHD risk among pupils: a multi-site longitudinal cohort study",
  "summary": "This study will examine whether exposure to fast-paced environments in home, school, and digital settings is associated with higher risk of incident attention-deficit/hyperactivity disorder (ADHD) and elevated symptom trajectories in primary school–aged pupils. A multi-site, prospective cohort with repeated measures will construct a Fast-Paced Environment Index (FPEI) and follow participants over 30 months, integrating multi-level modeling, quasi-experimental contrasts, and rigorous control for confounding to evaluate association, timing, dose-response, and potential mediators such as sleep disruption and executive function.",
  "research_questions": [
    "Is higher cumulative exposure to fast-paced environments associated with increased odds of incident ADHD over 30 months among pupils initially free of diagnosis?",
    "Is there a dose–response relationship between FPEI and ADHD symptom trajectories (inattention and hyperactivity/impulsivity) reported by teachers and parents?",
    "Which developmental windows (e.g., early vs. later primary school years) show the strongest associations?",
    "Do sleep patterns, stress indices, and executive function mediate the association?",
    "Do associations differ by sex, socioeconomic context, family history of ADHD, and urbanicity?"
  ],
  "hypotheses": [
    "Higher FPEI is associated with increased odds of incident ADHD diagnosis after adjusting for measured confounders.",
    "Higher FPEI is associated with steeper increases in ADHD symptom scores over time in a dose-responsive pattern.",
    "Associations are stronger for exposures accrued earlier in primary school.",
    "Sleep disruption and executive function deficits partially mediate observed associations.",
    "Associations are modified by family history of ADHD, sex, and socioeconomic context."
  ],
  "definitions": {
    "fast_paced_environment": "Contexts characterized by frequent rapid transitions, high novelty and time pressure, multi-tasking demands, and high-tempo media consumption across home, school, neighborhood, and digital domains.",
    "FPEI": "A standardized composite index capturing pace-related exposures across several domains, created from validated instruments, structured observations, and objective digital and schedule metrics.",
    "ADHD_outcomes": "Incident clinician-confirmed ADHD diagnosis based on DSM-5 criteria and longitudinal changes in validated symptom scales (e.g., ADHD-RS-5, Conners-3), from teacher and parent reports."
  },
  "study_design": {
    "type": "Prospective, multi-site longitudinal cohort with nested quasi-experimental contrasts",
    "duration_months": 54,
    "follow_up": {
      "frequency": "Every 6 months",
      "length_months": 30
    },
    "components": [
      "Cohort of pupils initially without ADHD diagnosis, followed for incident outcomes and symptom trajectories.",
      "Nested contrasts leveraging policy or schedule changes (e.g., school-level transition from short to block periods, smartphone policy changes) when feasible.",
      "Sibling comparison sub-analyses when siblings attend schools with differing pace profiles."
    ],
    "blinding": "Outcome assessors (clinicians) blinded to exposure measures and FPEI.",
    "registration": "Analysis plan preregistered on OSF before outcome data are inspected."
  },
  "sites_and_population": {
    "settings": "Urban and suburban public schools across three regions with varied class scheduling practices and digital device policies.",
    "target_sample_size": 5000,
    "anticipated_analyzable_sample": 4000,
    "age_range_years": "6–10 at enrollment",
    "inclusion_criteria": [
      "Enrollment in participating schools",
      "Guardian consent and child assent",
      "No clinician-confirmed ADHD diagnosis at baseline"
    ],
    "exclusion_criteria": [
      "Severe neurodevelopmental or neurological conditions that preclude valid assessment (e.g., severe intellectual disability, uncontrolled epilepsy)",
      "Insufficient language support capacity to obtain valid informed consent/assent after offering translation"
    ],
    "equity_and_access": "Provide multilingual materials, transportation vouchers for clinic visits, flexible scheduling, and device alternatives for participants lacking technology access."
  },
  "exposure_assessment": {
    "domains": [
      "School pace",
      "Home/daily schedule pace",
      "Digital media pace",
      "Neighborhood tempo"
    ],
    "school_pace": {
      "measures": [
        "Structured classroom observations capturing transitions per hour, duration of tasks, and frequency of rapid instruction shifts using standardized rubrics",
        "Administrative data on period length, passing time, and homework load",
        "Teacher surveys on pacing, classroom management strategies, and multitasking expectations"
      ]
    },
    "home_and_schedule": {
